package com.changyu.ochat;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class ResponsesBranchesRegressionTest {
 @Test public void protocolBodyAndBaseMapping()throws Exception{ChatApiClient c=new ChatApiClient().withModel(new JSONObject().put("reasoningLevels","none,high"));Method body=ChatApiClient.class.getDeclaredMethod("requestBody",String.class,JSONArray.class,double.class,int.class,double.class,String.class,String.class);body.setAccessible(true);JSONArray h=new JSONArray().put(new JSONObject().put("role","system").put("content","guide")).put(new JSONObject().put("role","user").put("content",new JSONArray().put(new JSONObject().put("type","text").put("text","hello")).put(new JSONObject().put("type","image_url").put("image_url",new JSONObject().put("url","data:image/png;base64,AA"))))).put(new JSONObject().put("role","assistant").put("content","old answer")).put(new JSONObject().put("role","system").put("content","Tavily turn guidance"));JSONObject b=(JSONObject)body.invoke(c,"fixture",h,.7,123,.9,"high","responses");assertFalse(b.getBoolean("store"));assertEquals(123,b.getInt("max_output_tokens"));assertFalse(b.has("messages"));assertEquals("guide",b.getString("instructions"));assertEquals(3,b.getJSONArray("input").length());JSONObject none=(JSONObject)body.invoke(c,"fixture",h,.7,123,.9,"none","responses");assertEquals("none",none.getJSONObject("reasoning").getString("effort"));assertEquals(.7,none.getDouble("temperature"),0);assertEquals(.9,none.getDouble("top_p"),0);assertEquals("high",b.getJSONObject("reasoning").getString("effort"));assertEquals("input_image",b.getJSONArray("input").getJSONObject(0).getJSONArray("content").getJSONObject(1).getString("type"));assertEquals("output_text",b.getJSONArray("input").getJSONObject(1).getJSONArray("content").getJSONObject(0).getString("type"));assertEquals("Tavily turn guidance",b.getJSONArray("input").getJSONObject(2).getJSONArray("content").getJSONObject(0).getString("text"));assertEquals("http://localhost/v1/responses",ChatApiClient.endpoint("http://localhost/v1/chat/completions/","responses"));assertEquals("http://localhost/v1/models",ChatApiClient.endpoint("http://localhost/v1/responses","models"));JSONObject legacy=new JSONObject();ModelStore.migrateProvider(legacy);assertEquals("chat_completions",legacy.getString("protocol"));}
 static class Sink implements ChatApiClient.StreamCallback{String text="",reasoning="",error="";int done;public void onDelta(String s){text+=s;}public void onSnapshot(String s){text=s;}public void onReasoning(String s){reasoning+=s;}public void onStatus(String s){}public void onDone(){done++;}public void onError(String s){error=s;}}
 private Sink stream(String fixture)throws Exception{Sink sink=new Sink();new ChatApiClient().parseSse(new ByteArrayInputStream(fixture.getBytes(StandardCharsets.UTF_8)),"responses",sink);return sink;}
 @Test public void framesMultilineDoneReplaceAndFinalOnly()throws Exception{Sink s=stream("event: response.output_text.delta\ndata: {\ndata: \"delta\":\"hel\",\"output_index\":0,\"content_index\":0}\n\nevent: response.output_text.delta\ndata: {\"delta\":\"lo\"}\n\nevent: response.output_text.done\ndata: {\"text\":\"hello!\"}\n\ndata: [DONE]\n\n");assertEquals("hello!",s.text);assertEquals(1,s.done);Sink finalOnly=stream("data: {\"type\":\"response.completed\",\"response\":{\"output\":[{\"type\":\"message\",\"content\":[{\"type\":\"output_text\",\"text\":\"canonical\"}]}]}}\n\n");assertEquals("canonical",finalOnly.text);assertEquals(1,finalOnly.done);}
 @Test public void outputOrderingIsolationAndReasoningSeparation()throws Exception{ResponseStream s=new ResponseStream();s.accept("response.output_text.delta",new JSONObject().put("output_index",1).put("delta","B"));s.accept("response.output_text.delta",new JSONObject().put("output_index",0).put("delta","A"));assertEquals("AB",s.text());assertEquals("",new ResponseStream().text());Sink x=stream("data: {\"type\":\"response.reasoning_summary_text.delta\",\"delta\":\"summary\"}\n\ndata: {\"type\":\"response.output_text.delta\",\"delta\":\"answer\"}");assertEquals("summary",x.reasoning);assertEquals("answer",x.text);}
 @Test public void sequenceDedupAndItemIdentity()throws Exception{ResponseStream s=new ResponseStream();s.accept("response.output_item.added",new JSONObject().put("output_index",2).put("item",new JSONObject().put("id","msg")));JSONObject delta=new JSONObject().put("item_id","msg").put("sequence_number",4).put("delta","hello");s.accept("response.output_text.delta",delta);s.accept("response.output_text.delta",delta);s.accept("response.output_text.delta",new JSONObject().put("output_index",0).put("delta","first"));assertEquals("firsthello",s.text());s.accept("response.output_text.done",new JSONObject().put("item_id","msg").put("text","final"));assertEquals("firstfinal",s.text());}
 @Test public void assistantRetrySwitchStaysOnParent()throws Exception{JSONObject session=new JSONObject().put("id","s").put("messages",new JSONArray().put(new JSONObject().put("id","u").put("user",true).put("text","question")).put(new JSONObject().put("id","a").put("user",false).put("text","answer")));ConversationBranches.edit(new JSONArray().put(session),"s","a",null,true);assertEquals("u",ConversationBranches.anchor(session));ConversationBranches.select(session,0);assertEquals("u",ConversationBranches.anchor(session));assertEquals("a",session.getJSONArray("messages").getJSONObject(1).getString("id"));}
 @Test public void cancellationAndRefusal()throws Exception{ChatApiClient.CancellationHandle handle=new ChatApiClient.CancellationHandle();handle.cancel();Sink s=new Sink();new ChatApiClient(handle).parseSse(new ByteArrayInputStream("data: [DONE]\n\n".getBytes(StandardCharsets.UTF_8)),"responses",s);assertEquals(0,s.done);try{new ResponseStream().accept("response.refusal.done",new JSONObject().put("refusal","no"));fail();}catch(IOException expected){assertTrue(expected.getMessage().startsWith("refusal"));}assertEquals("partial",ChatResponseParser.parse(new JSONObject("{\"status\":\"incomplete\",\"output\":[{\"type\":\"message\",\"content\":[{\"type\":\"output_text\",\"text\":\"partial\"}]}]}"),false));}
 @Test public void branchPersistenceDownstreamAndMetadata()throws Exception{JSONObject session=new JSONObject().put("id","s").put("title","manual").put("messages",new JSONArray().put(new JSONObject().put("id","u").put("user",true).put("text","old").put("attachments",new JSONArray().put("fixture"))).put(new JSONObject().put("id","a").put("user",false).put("text","answer").put("timestamp",123).put("modelId","local")).put(new JSONObject().put("id","later").put("user",true).put("text","followup")));JSONArray all=new JSONArray().put(session);ConversationBranches.edit(all,"s","u","edited",true);assertEquals(1,session.getJSONArray("messages").length());session.getJSONArray("messages").put(new JSONObject().put("id","new").put("text","new answer"));ConversationBranches.sync(session);JSONObject loaded=new JSONObject(session.toString());assertTrue(ConversationBranches.select(loaded,0));assertEquals(3,loaded.getJSONArray("messages").length());assertEquals("followup",loaded.getJSONArray("messages").getJSONObject(2).getString("text"));assertEquals(123,loaded.getJSONArray("messages").getJSONObject(1).getInt("timestamp"));assertTrue(ConversationBranches.select(loaded,1));assertEquals("edited",loaded.getJSONArray("messages").getJSONObject(0).getString("text"));assertEquals("new answer",loaded.getJSONArray("messages").getJSONObject(1).getString("text"));assertEquals("manual",loaded.getString("title"));assertEquals("fixture",loaded.getJSONArray("messages").getJSONObject(0).getJSONArray("attachments").getString(0));}
}
